import React, { useState, useRef } from 'react';
import './UploadFile.css';

const UploadFile = () => {
  const [files, setFiles] = useState([]);
  const [isDragging, setIsDragging] = useState(false);
  const fileInputRef = useRef(null);

  const handleDragOver = (e) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setIsDragging(false);
    const droppedFiles = Array.from(e.dataTransfer.files);
    handleFiles(droppedFiles);
  };

  const handleFileInput = (e) => {
    const selectedFiles = Array.from(e.target.files);
    handleFiles(selectedFiles);
  };

  const handleFiles = (newFiles) => {
    const updatedFiles = newFiles.map(file => ({
      name: file.name,
      size: formatFileSize(file.size),
      file
    }));
    setFiles(prev => [...prev, ...updatedFiles]);
  };

  const formatFileSize = (bytes) => {
    if (bytes === 0) return '0 B';
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(1024));
    return `${(bytes / Math.pow(1024, i)).toFixed(2)} ${sizes[i]}`;
  };

  const handleSelectFileClick = () => {
    fileInputRef.current.click();
  };

  const handleUpload = () => {
    // Handle the upload process here
    console.log('Uploading files:', files);
  };

  const handleCancel = () => {
    setFiles([]);
  };

  return (
    <div className="upload-container">
      <h2>Please Upload your Swagger Document</h2>
      <p className="upload-subtitle">Upload your Swagger YAML file (optional) and/or enter a custom prompt</p>

      <div 
        className={`upload-dropzone ${isDragging ? 'dragging' : ''}`}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
      >
        <div className="upload-icon">↑</div>
        <p>Select a file or drag and drop here</p>
        <p className="upload-size-limit">Maximum file size: 200 MB</p>
        <button className="select-file-btn" onClick={handleSelectFileClick}>
          SELECT FILE
        </button>
        <input
          type="file"
          ref={fileInputRef}
          onChange={handleFileInput}
          multiple
          accept=".yaml,.yml,.json"
          style={{ display: 'none' }}
        />
      </div>

      {files.length > 0 && (
        <div className="files-section">
          <h3>Files added</h3>
          <div className="files-list">
            {files.map((file, index) => (
              <div key={index} className="file-item">
                <div className="file-icon">📄</div>
                <div className="file-details">
                  <span className="file-name">{file.name}</span>
                  <span className="file-size">{file.size}</span>
                </div>
              </div>
            ))}
          </div>
          <div className="action-buttons">
            <button className="cancel-btn" onClick={handleCancel}>
              Cancel
            </button>
            <button className="upload-btn" onClick={handleUpload}>
              Upload
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default UploadFile;
